cetak(a, "-", b, "=", a - b);
cetak(a, "*", b, "=", a * b);
cetak(a, "/", b, "=", a / b);
cetak(a, "%", b, "=", a % b);
cetak(2, "^", 8, "=", 2 ^ 8);

// 3. Tipe Data
