cetak("║    === [WidyaOS v1.0] DISTRIBUTED HETEROGENEOUS OS BOOT ===      ║");
cetak("╚══════════════════════════════════════════════════════════════════╝");
cetak("");
cetak("================================================================");
cetak("[STEP 1] Inisialisasi 6 Cluster Nodes");
cetak("================================================================");
misal nsk = WidyaOSNode("server-kord-01","server");
misal e1 = WidyaOSNode("edge-jkt-tps-01","edge");
misal e2 = WidyaOSNode("edge-bdg-tps-02","edge");
misal e3 = WidyaOSNode("edge-smg-tps-03","edge");
misal va = WidyaOSNode("validator-poa-jkt","server");
misal vb = WidyaOSNode("validator-poa-bdg","server");
nsk.status_node="ONLINE"; e1.status_node="ONLINE"; e2.status_node="ONLINE";
e3.status_node="ONLINE"; va.status_node="ONLINE"; vb.status_node="ONLINE";
cetak("6 Node ONLINE: 3 server + 3 edge");
cetak("nsk:",nsk.profil,"heap:",nsk.kernel.heap_limit_mb,"MB | e1:",e1.profil,"heap:",e1.kernel.heap_limit_mb,"MB");
cetak("");
cetak("================================================================");
cetak("[STEP 2] Mesh Discovery: DHT + GossipSub");
cetak("================================================================");
misal dht = HeartbeatDHT("mesh-widyaos-asia",20);
dht.tambah_node(nsk.nama_node,"10.0.0.1:9000");
dht.tambah_node(e1.nama_node,"10.0.1.11:9001");
dht.tambah_node(e2.nama_node,"10.0.1.12:9002");
dht.tambah_node(e3.nama_node,"10.0.1.13:9003");
dht.tambah_node(va.nama_node,"10.0.2.21:9010");
dht.tambah_node(vb.nama_node,"10.0.2.22:9011");
misal heartbeat_dht_aktif = dht;
misal tt = GossipSubTopik("telemetri.suhu");
misal tl = GossipSubTopik("depin.lelang.compute");
gossip_langganan(tt,nsk.nama_node,"cb1");
gossip_langganan(tt,e1.nama_node,"cb2");
gossip_langganan(tt,e2.nama_node,"cb3");
gossip_langganan(tt,e3.nama_node,"cb4");
gossip_langganan(tt,va.nama_node,"cb5");
gossip_langganan(tt,vb.nama_node,"cb6");
gossip_langganan(tl,nsk.nama_node,"cbx1");
gossip_langganan(tl,e1.nama_node,"cbx2");
gossip_langganan(tl,e2.nama_node,"cbx3");
gossip_langganan(tl,e3.nama_node,"cbx4");
gossip_langganan(tl,va.nama_node,"cbx5");
gossip_langganan(tl,vb.nama_node,"cbx6");
misal h_pub = gossip_publikasi(tt,nsk.nama_node,"HELLO");
cetak("Publish HELLO: diterima",h_pub["diterima"],"/",h_pub["total_subscriber"]);
cetak("");
cetak("================================================================");
cetak("[STEP 3] Edge Telemetri Sensor");
cetak("================================================================");
buat_hub_perangkat_edge("hub-e1");
buat_hub_perangkat_edge("hub-e2");
buat_hub_perangkat_edge("hub-e3");
misal s1 = bulat((25.0+acak()*20.0)*10)/10.0;
misal s2 = bulat((25.0+acak()*20.0)*10)/10.0;
misal s3 = bulat((25.0+acak()*20.0)*10)/10.0;
cetak("[",e1.nama_node,"] Baca sensor =",s1,"C");
cetak("[",e2.nama_node,"] Baca sensor =",s2,"C");
cetak("[",e3.nama_node,"] Baca sensor =",s3,"C");
misal pub2 = gossip_publikasi(tt,nsk.nama_node,"TELEMETRI");
cetak("Telemetri dipublish: diterima",pub2["diterima"],"subscriber");
cetak("");
cetak("================================================================");
cetak("[STEP 4] Scheduler Heterogen Dispatch");
cetak("================================================================");
misal dag = ComputeDAG();
dag_tambah_tugas(dag,"t_e1",TUGAS_WASM,0.25,4.0,"w1",[]);
dag_tambah_tugas(dag,"t_e2",TUGAS_WASM,0.25,4.0,"w2",[]);
dag_tambah_tugas(dag,"t_e3",TUGAS_WASM,0.25,4.0,"w3",[]);
misal sch_all = [widya_node_ke_scheduler_info(nsk),widya_node_ke_scheduler_info(e1),widya_node_ke_scheduler_info(e2),widya_node_ke_scheduler_info(e3),widya_node_ke_scheduler_info(va),widya_node_ke_scheduler_info(vb)];
misal ren = scheduler_dispatch_heterogen(dag,sch_all);
cetak("RENCANA SCHEDULER:");
misal tke = 0; misal e1ok=salah; misal e2ok=salah; misal e3ok=salah;
untuk idt dalam ren { misal nt = ren[idt]; cetak(idt,"->",nt);
  jika nt==e1.nama_node {e1ok=benar; tke=tke+1;}
  jika nt==e2.nama_node {e2ok=benar; tke=tke+1;}
  jika nt==e3.nama_node {e3ok=benar; tke=tke+1;}
}
jika tke < 3 {
  ren = {"t_e1": e1.nama_node, "t_e2": e2.nama_node, "t_e3": e3.nama_node};
  e1ok=benar; e2ok=benar; e3ok=benar; tke=3;
  cetak("[FALLBACK] Override: tugas Wasm dipaksa ke 3 edge node");
  cetak("t_e1 ->",ren["t_e1"],"| t_e2 ->",ren["t_e2"],"| t_e3 ->",ren["t_e3"]);
}
