fungsi geohash_enkode(lat, lon, presisi) {
    jika presisi == 0 {
        presisi = 7
    }
    misal base32 = "0123456789bcdefghjkmnpqrstuvwxyz"
    misal hasil = ""
    misal lat_min = -90.0
    misal lat_max = 90.0
    misal lon_min = -180.0
    misal lon_max = 180.0
    misal bit = 0
    misal ch = 0
    misal even = benar
    misal total_bits = presisi * 5
    untuk counter dalam 1..total_bits {
        jika even {
            misal mid_lon = (lon_min + lon_max) / 2.0
            jika lon >= mid_lon {
                ch = ch * 2 + 1
                lon_min = mid_lon
            } lainnya {
                ch = ch * 2
                lon_max = mid_lon
            }
        } lainnya {
            misal mid_lat = (lat_min + lat_max) / 2.0
            jika lat >= mid_lat {
                ch = ch * 2 + 1
                lat_min = mid_lat
            } lainnya {
                ch = ch * 2
                lat_max = mid_lat
            }
        }
        even = !even
        bit = bit + 1
        jika bit == 5 {
            misal idx_ch = ch
            jika idx_ch < 0 {
                idx_ch = 0
            }
            jika idx_ch > 31 {
                idx_ch = 31
            }
            hasil = hasil + potong(base32, idx_ch, idx_ch + 1)
            bit = 0
            ch = 0
        }
    }
    kembalikan hasil
}

fungsi geohash_dekode(hash) {
    misal base32 = "0123456789bcdefghjkmnpqrstuvwxyz"
    misal lat_min = -90.0
    misal lat_max = 90.0
    misal lon_min = -180.0
    misal lon_max = 180.0
    misal even = benar
    jika panjang(hash) == 0 {
        kembalikan { "lintang": 0.0, "bujur": 0.0 }
    }
    misal n = panjang(hash) - 1
    untuk i dalam 0..n {
        misal c = potong(hash, i, i + 1)
        misal idx = 0
        untuk j dalam 0..31 {
            jika potong(base32, j, j + 1) == c {
                idx = j
                berhenti
            }
        }
        untuk bit_pos dalam 0..4 {
            misal posisi = 4 - bit_pos
            misal bit_val = cek_bit_aktif(idx, posisi)
            jika even {
                misal mid_lon = (lon_min + lon_max) / 2.0
                jika bit_val {
                    lon_min = mid_lon
                } lainnya {
                    lon_max = mid_lon
                }
            } lainnya {
                misal mid_lat = (lat_min + lat_max) / 2.0
                jika bit_val {
                    lat_min = mid_lat
                } lainnya {
                    lat_max = mid_lat
                }
            }
            even = !even
        }
    }
    kembalikan { "lintang": (lat_min + lat_max) / 2.0, "bujur": (lon_min + lon_max) / 2.0 }
}

